PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS login_attempts (id TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, window_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY, value_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings_audit (id TEXT PRIMARY KEY, category TEXT NOT NULL, old_json TEXT, new_json TEXT, version INTEGER NOT NULL, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS api_credentials (provider TEXT PRIMARY KEY, ciphertext TEXT NOT NULL, last4 TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS candles (symbol TEXT NOT NULL, tf TEXT NOT NULL, time INTEGER NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL, close REAL NOT NULL, volume REAL NOT NULL, source TEXT NOT NULL, PRIMARY KEY(symbol, tf, time));
CREATE TABLE IF NOT EXISTS quotes (symbol TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS meetings (id TEXT PRIMARY KEY, symbol TEXT NOT NULL, tf TEXT NOT NULL, at INTEGER NOT NULL, phase TEXT NOT NULL, value_json TEXT NOT NULL, UNIQUE(symbol,tf,at));
CREATE INDEX IF NOT EXISTS meeting_time ON meetings(at DESC);
CREATE TABLE IF NOT EXISTS meeting_dedup (symbol TEXT NOT NULL, tf TEXT NOT NULL, candle_time INTEGER NOT NULL, direction TEXT NOT NULL, PRIMARY KEY(symbol,tf,candle_time,direction));
CREATE TABLE IF NOT EXISTS signals (id TEXT PRIMARY KEY, symbol TEXT NOT NULL, tf TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, value_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS signal_status ON signals(status,created_at DESC);
CREATE TABLE IF NOT EXISTS signal_events (id TEXT PRIMARY KEY, signal_id TEXT NOT NULL REFERENCES signals(id), kind TEXT NOT NULL, price REAL, at INTEGER NOT NULL, value_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, symbol TEXT NOT NULL, price REAL NOT NULL CHECK(price>0), enabled INTEGER NOT NULL DEFAULT 1, fired INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, last_sent_at INTEGER);
CREATE TABLE IF NOT EXISTS alert_outbox (id TEXT PRIMARY KEY, content TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, retry_at INTEGER NOT NULL, created_at INTEGER NOT NULL, sent_at INTEGER);
CREATE TABLE IF NOT EXISTS source_events (id TEXT PRIMARY KEY, symbol TEXT NOT NULL, from_source TEXT, to_source TEXT, reason TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS service_log (id TEXT PRIMARY KEY, kind TEXT NOT NULL, message TEXT NOT NULL, at INTEGER NOT NULL);
